import { type ComponentProps, type ReactNode } from "react";
import { cn } from "./utils";

type BannerProps = Omit<ComponentProps<"div">, "title" | "children"> & {
    title: string;
    children?: ReactNode;
    variant?: "info" | "success" | "warning" | "error";
    action?: ReactNode;
    onDismiss?: () => void;
    closeLabel?: string;
};

function Banner({
    title, children, variant = "info", action, onDismiss,
    closeLabel = "공지 닫기", className, ...props
}: BannerProps) {
    return (
        <div {...props} data-ui="banner" data-surface="status"
            data-variant={variant} className={cn(
                "flex min-w-0 flex-wrap items-start gap-3 rounded-sm border " +
                "border-border border-l-4 bg-surface p-[var(--space-4)] " +
                "text-sm text-foreground",
                variant === "info" && "border-l-accent",
                variant === "success" && "border-l-success",
                variant === "warning" && "border-l-warning",
                variant === "error" && "border-l-danger",
                className,
            )}>
            <div className="min-w-0 flex-1 basis-48 [overflow-wrap:anywhere]"
                role={variant === "error" ? "alert" : "status"}
                aria-atomic="true">
                <p className="m-0 font-semibold">{title}</p>
                {children && <div className="mt-1 text-muted">{children}</div>}
            </div>
            {action && <div className="flex shrink-0 flex-wrap gap-2">{action}</div>}
            {onDismiss && <button type="button" aria-label={closeLabel}
                onClick={onDismiss} className={
                    "shrink-0 rounded-sm px-2 py-1 text-muted " +
                    "hover:bg-surface-subtle focus-visible:outline-2 " +
                    "focus-visible:outline-focus"
                }><span aria-hidden="true">×</span></button>}
        </div>
    );
}

export { Banner };
export type { BannerProps };
